/* ==========================================================================
   Redline Esports - Shared Stylesheet (Black, Red & White Theme)
   ========================================================================== */

:root {
  --bg-black: #09090b;
  --bg-dark: #111115;
  --bg-card: #18181e;
  --bg-card-hover: #202028;
  --red-primary: #e10600;
  --red-bright: #ff241c;
  --red-soft: rgba(225, 6, 0, 0.16);
  --white: #ffffff;
  --text-light: #e5e5ea;
  --text-muted: #a1a1aa;
  --border-color: rgba(255, 255, 255, 0.12);
  --border-red: rgba(225, 6, 0, 0.45);
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 14px;
  --shadow-card: 0 10px 28px rgba(0, 0, 0, 0.45);
  --transition: 0.2s ease;
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: "Segoe UI", system-ui, -apple-system, BlinkMacSystemFont, Roboto, sans-serif;
  background-color: var(--bg-black);
  color: var(--white);
  line-height: 1.6;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

img {
  display: block;
  max-width: 100%;
}

a {
  color: inherit;
  text-decoration: none;
}

button,
input,
select {
  font: inherit;
  color: inherit;
}

.container {
  width: min(1160px, 92%);
  margin-inline: auto;
}

/* Header & Navigation
   -------------------------------------------------------------------------- */

.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background-color: rgba(9, 9, 11, 0.96);
  backdrop-filter: blur(8px);
  border-bottom: 2px solid var(--red-primary);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.25rem;
  min-height: 74px;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 0.75rem;
  flex-shrink: 0;
}

.brand-logo {
  width: 42px;
  height: 42px;
}

.brand-name {
  font-size: 1.15rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--white);
}

.brand-name span {
  color: var(--red-primary);
}

.main-nav {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.nav-links {
  display: flex;
  align-items: center;
  list-style: none;
  gap: 0.35rem;
}

.nav-link {
  display: inline-block;
  padding: 0.5rem 0.9rem;
  border-radius: var(--radius-sm);
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--text-light);
  transition: background-color var(--transition), color var(--transition);
}

.nav-link:hover,
.nav-link:focus-visible {
  background-color: rgba(255, 255, 255, 0.08);
  color: var(--white);
}

.nav-link.active {
  background-color: var(--red-soft);
  color: var(--white);
  box-shadow: inset 0 -2px 0 var(--red-primary);
}

.btn-join {
  margin-left: 0.5rem;
  padding: 0.58rem 1.15rem;
  border: 1px solid var(--red-primary);
  border-radius: var(--radius-sm);
  background-color: var(--red-primary);
  color: var(--white);
  font-size: 0.92rem;
  font-weight: 700;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  cursor: pointer;
  transition: background-color var(--transition), transform var(--transition);
}

.btn-join:hover,
.btn-join:focus-visible {
  background-color: var(--red-bright);
  transform: translateY(-1px);
}

.nav-toggle {
  display: none;
  flex-direction: column;
  justify-content: center;
  gap: 5px;
  width: 42px;
  height: 42px;
  padding: 8px;
  background-color: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  cursor: pointer;
}

.nav-toggle-bar {
  width: 100%;
  height: 2px;
  background-color: var(--white);
  border-radius: 2px;
  transition: transform var(--transition), opacity var(--transition);
}

/* Main Content Wrapper
   -------------------------------------------------------------------------- */

main {
  flex: 1;
}

/* Footer
   -------------------------------------------------------------------------- */

.site-footer {
  margin-top: 4rem;
  background-color: var(--bg-dark);
  border-top: 2px solid var(--red-primary);
}

.footer-inner {
  display: grid;
  grid-template-columns: 1.5fr 1fr 1fr;
  gap: 2rem;
  padding: 2.5rem 0 2rem;
}

.footer-brand {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.footer-tagline {
  color: var(--text-muted);
  font-size: 0.92rem;
  max-width: 34ch;
}

.footer-heading {
  font-size: 0.9rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--white);
  margin-bottom: 0.85rem;
}

.footer-links {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.footer-links a {
  color: var(--text-muted);
  font-size: 0.92rem;
  transition: color var(--transition);
}

.footer-links a:hover,
.footer-links a:focus-visible {
  color: var(--red-bright);
}

.footer-cta-text {
  color: var(--text-muted);
  font-size: 0.92rem;
  margin-bottom: 0.9rem;
}

.footer-join-btn {
  margin-left: 0;
}

.footer-bottom {
  border-top: 1px solid var(--border-color);
  padding: 1rem 0;
  text-align: center;
  font-size: 0.85rem;
  color: var(--text-muted);
}

/* Join Redline Modal
   -------------------------------------------------------------------------- */

.modal-overlay {
  position: fixed;
  inset: 0;
  z-index: 200;
  display: grid;
  place-items: center;
  padding: 1rem;
  background-color: rgba(0, 0, 0, 0.78);
}

.modal-overlay[hidden] {
  display: none;
}

.modal-card {
  width: min(460px, 100%);
  background-color: var(--bg-card);
  border: 1px solid var(--border-red);
  border-radius: var(--radius-lg);
  padding: 1.75rem;
  box-shadow: var(--shadow-card);
}

.modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 1rem;
}

.modal-title {
  font-size: 1.25rem;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.modal-title span {
  color: var(--red-primary);
}

.modal-close {
  width: 34px;
  height: 34px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-color);
  background-color: var(--bg-dark);
  color: var(--white);
  font-size: 1.25rem;
  line-height: 1;
  cursor: pointer;
}

.modal-close:hover {
  border-color: var(--red-primary);
  color: var(--red-bright);
}

.modal-subtitle {
  color: var(--text-muted);
  font-size: 0.92rem;
  margin-bottom: 1.25rem;
}

.join-form {
  display: flex;
  flex-direction: column;
  gap: 0.95rem;
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

.form-group label {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--text-light);
}

.form-group input,
.form-group select {
  padding: 0.65rem 0.8rem;
  background-color: var(--bg-dark);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  font-size: 0.95rem;
}

.form-group input:focus,
.form-group select:focus {
  outline: none;
  border-color: var(--red-primary);
}

.join-submit {
  margin-top: 0.35rem;
  margin-left: 0;
  width: 100%;
  padding: 0.75rem;
}

.join-feedback {
  margin-top: 0.9rem;
  padding: 0.75rem;
  border-radius: var(--radius-sm);
  background-color: var(--red-soft);
  border: 1px solid var(--border-red);
  color: var(--white);
  font-size: 0.9rem;
}

/* Responsive Navigation & Footer
   -------------------------------------------------------------------------- */

@media (max-width: 860px) {
  .nav-toggle {
    display: flex;
  }

  .main-nav {
    display: none;
    position: absolute;
    top: 74px;
    left: 0;
    right: 0;
    flex-direction: column;
    align-items: stretch;
    gap: 0.75rem;
    padding: 1rem 4%;
    background-color: var(--bg-dark);
    border-bottom: 2px solid var(--red-primary);
  }

  .main-nav.is-open {
    display: flex;
  }

  .nav-links {
    flex-direction: column;
    align-items: stretch;
    gap: 0.35rem;
  }

  .nav-link {
    width: 100%;
    padding: 0.7rem 0.9rem;
  }

  .btn-join {
    margin-left: 0;
    width: 100%;
    text-align: center;
  }

  .footer-inner {
    grid-template-columns: 1fr;
    gap: 1.75rem;
  }
}

/* ==========================================================================
   Redline Esports - Match Results Page Styles
   ========================================================================== */

/* Hero Banner
   -------------------------------------------------------------------------- */

.page-hero {
  background:
    radial-gradient(circle at 85% 20%, rgba(225, 6, 0, 0.24), transparent 48%),
    linear-gradient(135deg, #0b0b0e 0%, #16161d 100%);
  border-bottom: 1px solid var(--border-color);
  padding: 3rem 0 2.5rem;
}

.page-eyebrow {
  display: inline-block;
  margin-bottom: 0.65rem;
  padding: 0.28rem 0.7rem;
  border-left: 3px solid var(--red-primary);
  background-color: rgba(255, 255, 255, 0.05);
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--text-light);
}

.page-hero h1 {
  font-size: clamp(1.9rem, 4vw, 2.75rem);
  font-weight: 800;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  margin-bottom: 0.55rem;
}

.page-hero h1 span {
  color: var(--red-primary);
}

.page-subtitle {
  max-width: 60ch;
  color: var(--text-muted);
  font-size: 1rem;
}

/* Summary Stats Strip
   -------------------------------------------------------------------------- */

.stats-section {
  padding-top: 1.75rem;
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1rem;
}

.stat-card {
  background-color: var(--bg-card);
  border: 1px solid var(--border-color);
  border-top: 3px solid var(--red-primary);
  border-radius: var(--radius-md);
  padding: 1rem 1.2rem;
}

.stat-label {
  display: block;
  font-size: 0.8rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-muted);
  margin-bottom: 0.25rem;
}

.stat-value {
  font-size: 1.75rem;
  font-weight: 800;
  color: var(--white);
}

/* Controls / Filters
   -------------------------------------------------------------------------- */

.results-section {
  padding-top: 2rem;
}

.controls-bar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  background-color: var(--bg-dark);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 1rem;
  margin-bottom: 1.15rem;
}

.status-filters {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.filter-btn {
  padding: 0.5rem 0.95rem;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  background-color: var(--bg-card);
  color: var(--text-light);
  font-size: 0.88rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color var(--transition), border-color var(--transition), color var(--transition);
}

.filter-btn:hover,
.filter-btn:focus-visible {
  border-color: var(--red-primary);
  color: var(--white);
}

.filter-btn.is-active {
  background-color: var(--red-primary);
  border-color: var(--red-primary);
  color: var(--white);
}

.search-controls {
  display: flex;
  flex-wrap: wrap;
  gap: 0.65rem;
  flex: 1;
  justify-content: flex-end;
}

.control-select,
.control-input {
  padding: 0.52rem 0.85rem;
  background-color: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  font-size: 0.9rem;
  min-width: 170px;
}

.control-select:focus,
.control-input:focus {
  outline: none;
  border-color: var(--red-primary);
}

.results-meta {
  font-size: 0.9rem;
  color: var(--text-muted);
  margin-bottom: 1rem;
}

/* Match Results Grid & Cards
   -------------------------------------------------------------------------- */

.match-results-list {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1.15rem;
}

.match-card {
  background-color: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 1.25rem;
  box-shadow: var(--shadow-card);
  transition: transform var(--transition), border-color var(--transition), background-color var(--transition);
}

.match-card:hover {
  transform: translateY(-2px);
  border-color: var(--border-red);
  background-color: var(--bg-card-hover);
}

.match-card-top {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.6rem;
  padding-bottom: 0.9rem;
  margin-bottom: 1rem;
  border-bottom: 1px solid var(--border-color);
}

.match-info {
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
}

.match-game {
  font-size: 0.78rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--red-bright);
}

.match-tournament {
  font-size: 0.92rem;
  font-weight: 600;
  color: var(--white);
}

.match-meta-right {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 0.3rem;
}

.match-status {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.24rem 0.65rem;
  border-radius: 999px;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.status-completed {
  background-color: rgba(255, 255, 255, 0.12);
  color: var(--white);
  border: 1px solid rgba(255, 255, 255, 0.22);
}

.status-live {
  background-color: var(--red-primary);
  color: var(--white);
}

.status-live::before {
  content: "";
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background-color: var(--white);
  animation: livePulse 1.4s infinite;
}

.status-upcoming {
  background-color: transparent;
  color: var(--text-light);
  border: 1px solid var(--border-red);
}

@keyframes livePulse {
  0%,
  100% {
    opacity: 1;
    transform: scale(1);
  }
  50% {
    opacity: 0.4;
    transform: scale(0.8);
  }
}

.match-date {
  font-size: 0.8rem;
  color: var(--text-muted);
}

/* Matchup Row */

.matchup-row {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 0.85rem;
}

.team-block {
  display: flex;
  align-items: center;
  gap: 0.7rem;
  min-width: 0;
}

.team-block.team-right {
  flex-direction: row-reverse;
  text-align: right;
}

.team-logo {
  width: 44px;
  height: 44px;
  flex-shrink: 0;
}

.team-details {
  min-width: 0;
}

.team-name {
  font-size: 0.98rem;
  font-weight: 700;
  color: var(--white);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.team-tag {
  font-size: 0.76rem;
  color: var(--text-muted);
}

.team-block.is-winner .team-name {
  color: var(--white);
}

.team-block.is-winner .team-tag {
  color: var(--red-bright);
  font-weight: 700;
}

.score-box {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.45rem;
  padding: 0.5rem 0.9rem;
  background-color: var(--bg-dark);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  min-width: 88px;
}

.score-num {
  font-size: 1.35rem;
  font-weight: 800;
  color: var(--white);
}

.score-num.is-leading {
  color: var(--red-bright);
}

.score-divider {
  color: var(--text-muted);
  font-weight: 700;
}

.score-vs {
  font-size: 0.92rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  color: var(--text-light);
}

/* Empty State */

.empty-state {
  text-align: center;
  padding: 2.75rem 1.25rem;
  background-color: var(--bg-card);
  border: 1px dashed var(--border-color);
  border-radius: var(--radius-lg);
}

.empty-state[hidden] {
  display: none;
}

.empty-state h2 {
  font-size: 1.2rem;
  margin-bottom: 0.4rem;
}

.empty-state p {
  color: var(--text-muted);
  margin-bottom: 1rem;
}

/* Responsive Breakpoints
   -------------------------------------------------------------------------- */

@media (max-width: 960px) {
  .match-results-list {
    grid-template-columns: 1fr;
  }

  .stats-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 640px) {
  .page-hero {
    padding: 2.25rem 0 1.85rem;
  }

  .controls-bar {
    flex-direction: column;
    align-items: stretch;
  }

  .search-controls {
    flex-direction: column;
    justify-content: stretch;
  }

  .control-select,
  .control-input {
    width: 100%;
  }

  .match-meta-right {
    align-items: flex-start;
  }

  .matchup-row {
    grid-template-columns: 1fr;
    gap: 0.75rem;
  }

  .team-block.team-right {
    flex-direction: row;
    text-align: left;
  }

  .score-box {
    justify-self: start;
  }
}

/* ==========================================================================
   Redline Esports - Shared Navigation & Join Modal Logic
   ========================================================================== */

document.addEventListener("DOMContentLoaded", () => {
  const navToggle = document.getElementById("navToggle");
  const mainNav = document.getElementById("mainNav");
  const joinModal = document.getElementById("joinModal");
  const closeJoinBtn = document.getElementById("closeJoinModal");
  const openJoinButtons = document.querySelectorAll("[data-open-join]");
  const joinForm = document.getElementById("joinForm");
  const joinFeedback = document.getElementById("joinFeedback");

  // Toggle mobile navigation drawer
  if (navToggle && mainNav) {
    navToggle.addEventListener("click", () => {
      const isOpen = mainNav.classList.toggle("is-open");
      navToggle.setAttribute("aria-expanded", String(isOpen));
    });
  }

  function openModal() {
    if (!joinModal) return;
    joinModal.hidden = false;
    if (mainNav && mainNav.classList.contains("is-open")) {
      mainNav.classList.remove("is-open");
      if (navToggle) navToggle.setAttribute("aria-expanded", "false");
    }
    const nameInput = document.getElementById("joinName");
    if (nameInput) nameInput.focus();
  }

  function closeModal() {
    if (!joinModal) return;
    joinModal.hidden = true;
  }

  openJoinButtons.forEach((button) => {
    button.addEventListener("click", openModal);
  });

  if (closeJoinBtn) {
    closeJoinBtn.addEventListener("click", closeModal);
  }

  if (joinModal) {
    joinModal.addEventListener("click", (event) => {
      if (event.target === joinModal) {
        closeModal();
      }
    });
  }

  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape" && joinModal && !joinModal.hidden) {
      closeModal();
    }
  });

  if (joinForm && joinFeedback) {
    joinForm.addEventListener("submit", (event) => {
      event.preventDefault();
      const playerName = document.getElementById("joinName").value.trim();
      const game = document.getElementById("joinGame").value;

      joinFeedback.textContent = `Thanks, ${playerName}! Your interest for ${game} has been recorded for Redline Esports.`;
      joinFeedback.hidden = false;
      joinForm.reset();
    });
  }
});

