const STATUS_LABELS = {
  completed: "Completed",
  live: "Live",
  upcoming: "Upcoming",
};

document.addEventListener("DOMContentLoaded", () => {
  const resultsContainer = document.getElementById("matchResultsList");
  const resultsMeta = document.getElementById("resultsMeta");
  const emptyState = document.getElementById("emptyState");
  const filterButtons = document.querySelectorAll(".filter-btn");
  const gameFilter = document.getElementById("gameFilter");
  const teamSearch = document.getElementById("teamSearch");
  const resetFiltersBtn = document.getElementById("resetFiltersBtn");

  const state = {
    status: "all",
    game: "all",
    search: "",
  };

  function updateSummaryStats() {
    const counts = {
      total: MATCHES.length,
      live: MATCHES.filter((m) => m.status === "live").length,
      completed: MATCHES.filter((m) => m.status === "completed").length,
      upcoming: MATCHES.filter((m) => m.status === "upcoming").length,
    };

    document.getElementById("statTotal").textContent = counts.total;
    document.getElementById("statLive").textContent = counts.live;
    document.getElementById("statCompleted").textContent = counts.completed;
    document.getElementById("statUpcoming").textContent = counts.upcoming;
  }

  function createTeamElement(name, logoPath, isRightSide, isWinner) {
    const teamBlock = document.createElement("div");
    teamBlock.className = "team-block";
    if (isRightSide) teamBlock.classList.add("team-right");
    if (isWinner) teamBlock.classList.add("is-winner");

    const logo = document.createElement("img");
    logo.className = "team-logo";
    logo.src = logoPath;
    logo.alt = `${name} Logo`;

    const details = document.createElement("div");
    details.className = "team-details";

    const nameEl = document.createElement("div");
    nameEl.className = "team-name";
    nameEl.textContent = name;

    const tagEl = document.createElement("div");
    tagEl.className = "team-tag";
    tagEl.textContent = isWinner ? "Winner" : "Squad";

    details.append(nameEl, tagEl);
    teamBlock.append(logo, details);
    return teamBlock;
  }

  function createScoreElement(match) {
    const scoreBox = document.createElement("div");
    scoreBox.className = "score-box";

    if (match.status === "upcoming") {
      const vs = document.createElement("span");
      vs.className = "score-vs";
      vs.textContent = "VS";
      scoreBox.appendChild(vs);
      return scoreBox;
    }

    const leftScore = document.createElement("span");
    leftScore.className = "score-num";
    leftScore.textContent = match.scoreA;
    if (match.scoreA > match.scoreB) leftScore.classList.add("is-leading");

    const divider = document.createElement("span");
    divider.className = "score-divider";
    divider.textContent = ":";

    const rightScore = document.createElement("span");
    rightScore.className = "score-num";
    rightScore.textContent = match.scoreB;
    if (match.scoreB > match.scoreA) rightScore.classList.add("is-leading");

    scoreBox.append(leftScore, divider, rightScore);
    return scoreBox;
  }

  function createMatchCard(match) {
    const card = document.createElement("article");
    card.className = "match-card";

    // Top metadata row (game, tournament, status badge, match date)
    const topRow = document.createElement("div");
    topRow.className = "match-card-top";

    const info = document.createElement("div");
    info.className = "match-info";

    const gameEl = document.createElement("span");
    gameEl.className = "match-game";
    gameEl.textContent = match.game;

    const tournamentEl = document.createElement("span");
    tournamentEl.className = "match-tournament";
    tournamentEl.textContent = match.tournament;

    info.append(gameEl, tournamentEl);

    const metaRight = document.createElement("div");
    metaRight.className = "match-meta-right";

    const statusBadge = document.createElement("span");
    statusBadge.className = `match-status status-${match.status}`;
    statusBadge.textContent = STATUS_LABELS[match.status] || match.status;

    const dateEl = document.createElement("span");
    dateEl.className = "match-date";
    dateEl.textContent = match.date;

    metaRight.append(statusBadge, dateEl);
    topRow.append(info, metaRight);

    // Matchup row (team A, score, team B)
    const matchupRow = document.createElement("div");
    matchupRow.className = "matchup-row";

    const isCompleted = match.status === "completed";
    const teamAWon = isCompleted && match.scoreA > match.scoreB;
    const teamBWon = isCompleted && match.scoreB > match.scoreA;

    matchupRow.append(
      createTeamElement(match.teamA, match.logoA, false, teamAWon),
      createScoreElement(match),
      createTeamElement(match.teamB, match.logoB, true, teamBWon)
    );

    card.append(topRow, matchupRow);
    return card;
  }

  function renderMatches() {
    const query = state.search.toLowerCase();

    const filtered = MATCHES.filter((match) => {
      const matchesStatus = state.status === "all" || match.status === state.status;
      const matchesGame = state.game === "all" || match.game === state.game;
      const matchesTeam =
        !query ||
        match.teamA.toLowerCase().includes(query) ||
        match.teamB.toLowerCase().includes(query);

      return matchesStatus && matchesGame && matchesTeam;
    });

    resultsContainer.replaceChildren(...filtered.map(createMatchCard));
    resultsMeta.textContent = `Showing ${filtered.length} of ${MATCHES.length} matches`;
    emptyState.hidden = filtered.length > 0;
  }

  filterButtons.forEach((button) => {
    button.addEventListener("click", () => {
      filterButtons.forEach((btn) => btn.classList.remove("is-active"));
      button.classList.add("is-active");
      state.status = button.dataset.status;
      renderMatches();
    });
  });

  gameFilter.addEventListener("change", () => {
    state.game = gameFilter.value;
    renderMatches();
  });

  teamSearch.addEventListener("input", () => {
    state.search = teamSearch.value.trim();
    renderMatches();
  });

  resetFiltersBtn.addEventListener("click", () => {
    state.status = "all";
    state.game = "all";
    state.search = "";

    filterButtons.forEach((btn) => {
      btn.classList.toggle("is-active", btn.dataset.status === "all");
    });
    gameFilter.value = "all";
    teamSearch.value = "";
    renderMatches();
  });

  updateSummaryStats();
  renderMatches();
});

/* ==========================================================================
   Redline Esports - Shared Stylesheet (Black, Red & White Theme)
   ========================================================================== */

:root {
  --bg-black: #0a0a0c;
