  --text-muted: #a1a1aa;
  --border-color: rgba(255, 255, 255, 0.22);
  --border-subtle: rgba(255, 255, 255, 0.12);
  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --transition: 0.2s ease;
}

*,
*::before,
