document.addEventListener("DOMContentLoaded", () => {
  const menuToggle = document.getElementById("menuToggle");
  const pagesDropdown = document.getElementById("pagesDropdown");
  const joinModal = document.getElementById("joinModal");
  const openJoinBtn = document.getElementById("openJoinModal");
  const joinForm = document.getElementById("joinForm");
  const joinFeedback = document.getElementById("joinFeedback");

  function closeDropdown() {
    if (!pagesDropdown || !menuToggle) return;
    pagesDropdown.hidden = true;
    menuToggle.setAttribute("aria-expanded", "false");
  }

  function closeAllModals() {
    document.querySelectorAll(".modal-overlay").forEach((modal) => {
      modal.hidden = true;
    });
  }

  if (menuToggle && pagesDropdown) {
    menuToggle.addEventListener("click", (event) => {
      event.stopPropagation();
      const willOpen = pagesDropdown.hidden;
      pagesDropdown.hidden = !willOpen;
      menuToggle.setAttribute("aria-expanded", String(willOpen));
    });

    document.addEventListener("click", (event) => {
      if (!pagesDropdown.hidden && !pagesDropdown.contains(event.target) && event.target !== menuToggle) {
        closeDropdown();
      }
    });
  }

  if (openJoinBtn && joinModal) {
    openJoinBtn.addEventListener("click", () => {
      closeDropdown();
      joinModal.hidden = false;
      const nameInput = document.getElementById("joinName");
      if (nameInput) nameInput.focus();
    });
  }

  document.querySelectorAll("[data-close-modal]").forEach((btn) => {
    btn.addEventListener("click", closeAllModals);
  });

  document.querySelectorAll(".modal-overlay").forEach((modal) => {
    modal.addEventListener("click", (event) => {
      if (event.target === modal) {
        modal.hidden = true;
      }
    });
  });

  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape") {
      closeDropdown();
      closeAllModals();
    }
  });

  if (joinForm && joinFeedback) {
    joinForm.addEventListener("submit", (event) => {
      event.preventDefault();
      const name = document.getElementById("joinName").value.trim();
      const game = document.getElementById("joinGame").value;
      joinFeedback.textContent = `Thanks, ${name}! Your ${game} registration request has been recorded.`;
      joinFeedback.hidden = false;
      joinForm.reset();
    });
  }
});

/* ==========================================================================
   Redline Esports - Match Results Table Filtering & Details Modal
   ========================================================================== */

const MATCHES = [
  {
    id: 1,
    date: "22 Nov",
    game: "Valorant",
    teamA: "Nuces Raptors",
    teamB: "FAST Legends",
    score: "2-0",
    winner: "Nuces Raptors",
    status: "Completed",
    tournament: "FAST NUCES Valorant Cup",
    notes: "Nuces Raptors won Ascent (13-8) and Bind (13-10).",
  },
  {
    id: 2,
    date: "21 Nov",
    game: "CS2",
    teamA: "Campus Dragons",
    teamB: "Redline Stars",
    score: "1-2",
    winner: "Redline Stars",
    status: "Completed",
    tournament: "Redline CS2 Championship",
    notes: "Redline Stars came back after dropping Mirage to win Inferno and Ancient.",
  },
  {
    id: 3,
    date: "20 Nov",
    game: "BGMI",
    teamA: "FAST Legends",
    teamB: "BGMI Fighters",
    score: "2-1",
    winner: "FAST Legends",
    status: "Completed",
    tournament: "Inter-Department BGMI Clash",
    notes: "FAST Legends secured two Chicken Dinners across three Erangel & Miramar rounds.",
  },
];

document.addEventListener("DOMContentLoaded", () => {
  const tableBody = document.getElementById("matchesTableBody");
  const filterButtons = document.querySelectorAll(".filter-pill");
  const detailsModal = document.getElementById("detailsModal");
  const detailsContent = document.getElementById("detailsContent");

  let activeGame = "all";

  function openMatchDetails(match) {
    const items = [
      ["Date", match.date],
      ["Game", match.game],
      ["Tournament", match.tournament],
      ["Matchup", `${match.teamA} vs ${match.teamB}`],
      ["Score", match.score],
      ["Winner", match.winner],
      ["Status", match.status],
      ["Summary", match.notes],
    ];

    const rows = items.map(([label, value]) => {
      const row = document.createElement("div");
      row.className = "details-row";

      const labelEl = document.createElement("span");
      labelEl.className = "details-label";
      labelEl.textContent = label;

      const valueEl = document.createElement("span");
      valueEl.className = "details-value";
      valueEl.textContent = value;

      row.append(labelEl, valueEl);
      return row;
    });

    detailsContent.replaceChildren(...rows);
    detailsModal.hidden = false;
  }

  function createMatchRow(match) {
    const tr = document.createElement("tr");

    const dateTd = document.createElement("td");
    dateTd.className = "date-cell";
    dateTd.setAttribute("data-label", "Date");
    dateTd.textContent = match.date;

    const teamsTd = document.createElement("td");
    teamsTd.className = "teams-cell";
    teamsTd.setAttribute("data-label", "Teams");

    const teamAEl = document.createElement("span");
    teamAEl.className = "team-line";
    teamAEl.textContent = match.teamA;

    const vsEl = document.createElement("span");
    vsEl.className = "vs-line";
    vsEl.textContent = "vs";

    const teamBEl = document.createElement("span");
    teamBEl.className = "team-line";
    teamBEl.textContent = match.teamB;

    teamsTd.append(teamAEl, vsEl, teamBEl);

    const scoreTd = document.createElement("td");
    scoreTd.className = "score-cell";
    scoreTd.setAttribute("data-label", "Score");
    scoreTd.textContent = match.score;

    const winnerTd = document.createElement("td");
    winnerTd.className = "winner-cell";
    winnerTd.setAttribute("data-label", "Winner");
    winnerTd.textContent = match.winner;

    const actionTd = document.createElement("td");
    actionTd.setAttribute("data-label", "Action");

    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "btn-details";
    btn.textContent = "View Details";
    btn.addEventListener("click", () => openMatchDetails(match));

    actionTd.appendChild(btn);
    tr.append(dateTd, teamsTd, scoreTd, winnerTd, actionTd);
    return tr;
  }

  function renderTable() {
    const filtered =
      activeGame === "all"
        ? MATCHES
        : MATCHES.filter((match) => match.game === activeGame);

    tableBody.replaceChildren(...filtered.map(createMatchRow));
  }

  filterButtons.forEach((button) => {
    button.addEventListener("click", () => {
      filterButtons.forEach((btn) => btn.classList.remove("is-active"));
      button.classList.add("is-active");
      activeGame = button.dataset.game;
      renderTable();
    });
  });

  renderTable();
});

