/* ==========================================================================
   Redline Esports - Match Results Table Filtering & Navigation
   ========================================================================== */

document.addEventListener("DOMContentLoaded", () => {
  const tableBody = document.getElementById("matchesTableBody");
  const filterButtons = document.querySelectorAll(".filter-pill");

  let activeGame = "all";

  function createMatchRow(match) {
    const tr = document.createElement("tr");

    const dateTd = document.createElement("td");
    dateTd.className = "date-cell";
    dateTd.setAttribute("data-label", "Date");
    dateTd.textContent = match.date;

    const teamsTd = document.createElement("td");
    teamsTd.className = "teams-cell";
    teamsTd.setAttribute("data-label", "Teams");

    const teamAEl = document.createElement("span");
    teamAEl.className = "team-line";
    teamAEl.textContent = match.teamA;

    const vsEl = document.createElement("span");
    vsEl.className = "vs-line";
    vsEl.textContent = "vs";

    const teamBEl = document.createElement("span");
    teamBEl.className = "team-line";
    teamBEl.textContent = match.teamB;

    teamsTd.append(teamAEl, vsEl, teamBEl);

    const scoreTd = document.createElement("td");
    scoreTd.className = "score-cell";
    scoreTd.setAttribute("data-label", "Score");
    scoreTd.textContent = match.score;

    const winnerTd = document.createElement("td");
    winnerTd.className = "winner-cell";
    winnerTd.setAttribute("data-label", "Winner");
    winnerTd.textContent = match.winner;

    const actionTd = document.createElement("td");
    actionTd.setAttribute("data-label", "Action");

    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "btn-details";
    btn.textContent = "View Details";
    btn.addEventListener("click", () => {
      window.location.href = `match-details.html?id=${match.id}`;
    });

    actionTd.appendChild(btn);
    tr.append(dateTd, teamsTd, scoreTd, winnerTd, actionTd);
    return tr;
  }

  function renderTable() {
    const filtered =
      activeGame === "all"
        ? MATCHES
        : MATCHES.filter((match) => match.game === activeGame);

    tableBody.replaceChildren(...filtered.map(createMatchRow));
  }

  filterButtons.forEach((button) => {
    button.addEventListener("click", () => {
      filterButtons.forEach((btn) => btn.classList.remove("is-active"));
      button.classList.add("is-active");
      activeGame = button.dataset.game;
      renderTable();
    });
  });

  renderTable();
});

/* ==========================================================================
   Redline Esports - Match Details Page Styles (Vertical Prototype Layout)
   ========================================================================== */

.details-page {
  padding: 3rem 0 1rem;
}

.details-top-bar {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 1.75rem;
}

.page-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 0.65rem;
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--red);
  margin-bottom: 0.65rem;
}

.page-eyebrow::before {
  content: "";
  width: 24px;
  height: 2px;
  background-color: var(--red);
}

.page-title {
  font-size: clamp(2rem, 4vw, 2.85rem);
  font-weight: 900;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  line-height: 1.1;
}

.page-title span {
  color: var(--red);
}

.btn-back {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  padding: 0.55rem 1.15rem;
  background-color: var(--bg-surface);
  border: 1px solid var(--border-strong);
  border-radius: 999px;
  font-size: 0.86rem;
  font-weight: 700;
  color: var(--white);
  transition: border-color var(--transition), background-color var(--transition);
}

.btn-back:hover,
.btn-back:focus-visible {
  border-color: var(--red);
  background-color: var(--red-soft);
}

/* Two-Column Match Details Card (Prototype Layout)
   -------------------------------------------------------------------------- */

.details-panel {
  display: grid;
  grid-template-columns: minmax(260px, 1fr) minmax(0, 1.25fr);
  background-color: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  overflow: hidden;
}

/* Left Column: Image Box + See <Game> Leaderboard Button */

.details-media-col {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 1.25rem;
  padding: 2rem;
  border-right: 1px solid var(--border-subtle);
}

.details-image-box {
  width: 100%;
  aspect-ratio: 16 / 10;
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-md);
  overflow: hidden;
  background-color: var(--bg-page);
}

.details-image-box img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.btn-leaderboard {
  display: inline-block;
  padding: 0.65rem 1.4rem;
  background-color: var(--red);
  border: 1px solid var(--red);
  border-radius: 999px;
  color: var(--white);
  font-size: 0.88rem;
  font-weight: 700;
  text-align: center;
  transition: background-color var(--transition);
}

.btn-leaderboard:hover,
.btn-leaderboard:focus-visible {
  background-color: var(--red-dark);
}

/* Right Column: Matchup, Score, Date, Map, Top Player */

.details-info-col {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 1.35rem;
  padding: 2.25rem;
}

.matchup-heading {
  font-size: clamp(1.35rem, 2.5vw, 1.8rem);
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  line-height: 1.25;
  color: var(--white);
}

.matchup-vs {
  display: block;
  font-size: 0.95rem;
  font-weight: 800;
  color: var(--red);
  margin: 0.2rem 0;
}

.match-stats-list {
  display: flex;
  flex-direction: column;
  gap: 0.7rem;
  padding: 1rem 0;
  border-top: 1px solid var(--border-subtle);
  border-bottom: 1px solid var(--border-subtle);
}

.stat-line {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  font-size: 1rem;
}

.stat-label {
  font-weight: 700;
  color: var(--text-muted);
}

.stat-value {
  font-weight: 700;
  color: var(--white);
}

.top-player-section {
  display: flex;
  flex-direction: column;
  gap: 0.65rem;
}

.top-player-label {
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--text-muted);
}

.top-player-card {
  display: inline-flex;
  align-items: center;
  gap: 0.9rem;
}

.player-avatar {
  width: 54px;
  height: 54px;
  border-radius: 50%;
  flex-shrink: 0;
}

.top-player-name {
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--white);
}

/* Responsive Breakpoints
   -------------------------------------------------------------------------- */

@media (max-width: 820px) {
  .details-panel {
    grid-template-columns: 1fr;
  }

  .details-media-col {
    border-right: none;
    border-bottom: 1px solid var(--border-subtle);
    padding: 1.5rem;
  }

  .details-info-col {
    padding: 1.5rem;
  }
}

@media (max-width: 620px) {
  .details-page {
    padding-top: 2rem;
  }

  .btn-leaderboard {
    width: 100%;
  }
}

